"""

    ***WARNING***: This file has been generated by AI and has not been heavily check or modified. This code
    is not guaranteed to be successful and was used as a proof of concept
 
    Setup: a tracker node (with GPS) rides on the drone and broadcasts its position over LoRa.
    A second Meshtastic node is plugged into this computer by USB and receives it.
    
    Run this file directly to test the link, or import PositionFeed from the detection script:
    
        feed = PositionFeed()
        fix = feed.nearest(frame_arrival_time - STREAM_DELAY_S)
"""
import bisect
import threading
import time
 
import meshtastic.serial_interface
from pubsub import pub
 
TRACKER_ID =  None          # e.g. "!a1b2c3d4" to ignore other nodes; None accepts positions from any node
SERIAL_PORT = None          # e.g. "COM5"; None lets the library look for the node itself
 
 
class PositionFeed:
    def __init__(self, port=SERIAL_PORT, tracker_id=TRACKER_ID, max_history=3600):
        self.tracker_id = tracker_id
        self.max_history = max_history
        self.lock = threading.Lock()
        self.times = []  # when each fix arrived here (time.time()), ascending
        self.fixes = []  # matching dicts: lat, lon, alt, node_time, node
        pub.subscribe(self._on_position, "meshtastic.receive.position")
        self.interface = meshtastic.serial_interface.SerialInterface(port)
 
    def _on_position(self, packet, interface):
        if self.tracker_id and packet.get("fromId") != self.tracker_id:
            return
 
        pos = packet.get("decoded", {}).get("position", {})
 
        # the library may give decimal degrees directly, or integers scaled by 1e7
        lat = pos.get("latitude")
        lon = pos.get("longitude")
        if lat is None and pos.get("latitudeI") is not None:
            lat = pos["latitudeI"] * 1e-7
        if lon is None and pos.get("longitudeI") is not None:
            lon = pos["longitudeI"] * 1e-7
        if lat is None or lon is None:
            return
 
        fix = {
            "lat": lat,
            "lon": lon,
            "alt": pos.get("altitude"),
            "node_time": pos.get("time"),  # time stamped by the tracker's GPS, when present
            "node": packet.get("fromId"),
        }
        now = time.time()
        with self.lock:
            self.times.append(now)
            self.fixes.append(fix)
            if len(self.times) > self.max_history:
                del self.times[0]
                del self.fixes[0]
 
    def latest(self):
        with self.lock:
            if not self.times:
                return None
            return {**self.fixes[-1], "fix_arrival": self.times[-1]}
 
    def nearest(self, t, max_gap=15.0):
        """Fix whose arrival time is closest to t (seconds since epoch).
 
        Returns None if there is no fix within max_gap seconds, so an old
        position is never attached to a detection by accident.
        """
        with self.lock:
            if not self.times:
                return None
            i = bisect.bisect_left(self.times, t)
            candidates = [j for j in (i - 1, i) if 0 <= j < len(self.times)]
            j = min(candidates, key=lambda k: abs(self.times[k] - t))
            gap = abs(self.times[j] - t)
            if gap > max_gap:
                return None
            return {**self.fixes[j], "fix_arrival": self.times[j], "gap_s": gap}
 
    def close(self):
        self.interface.close()
 
 
if __name__ == "__main__":
    feed = PositionFeed()
    print("Listening for positions... (Ctrl+C to stop)")
    last_seen = None
    try:
        while True:
            time.sleep(0.5)
            fix = feed.latest()
            if fix and fix["fix_arrival"] != last_seen:
                interval = "" if last_seen is None else f"  (+{fix['fix_arrival'] - last_seen:.1f}s)"
                print(f"{fix['node']}  lat={fix['lat']:.6f}  lon={fix['lon']:.6f}  alt={fix['alt']}{interval}")
                last_seen = fix["fix_arrival"]
    except KeyboardInterrupt:
        pass
    finally:
        feed.close()